OFF_sales_commission_payroll.invariants_dsl:
spec CommissionPayroll {
    field base_salary: Number {
        value >= 2000.0;
        value <= 20000.0;
    }
    field sales_amount: Number {
        value >= 0.0;
        value <= 500000.0;
    }
    field commission_rate_pct: Number {
        value >= 1.0;
        value <= 15.0;
    }
    field commission_earned: Number {
        value == this.sales_amount * (this.commission_rate_pct / 100.0);
    }
    field gross_pay: Number {
        value == this.base_salary + this.commission_earned;
    }
    field tax_rate_pct: Number {
        value >= 10.0;
        value <= 35.0;
    }
    field tax_withheld: Number {
        value == this.gross_pay * (this.tax_rate_pct / 100.0);
    }
    field net_pay: Number {
        value == this.gross_pay - this.tax_withheld;
    }
}

OFF_forex_conversion_fee.invariants_dsl:
spec ForexTransaction {
    field source_amount: Number {
        value >= 10.0;
        value <= 1000000.0;
    }
    field exchange_rate: Number {
        value >= 0.5;
        value <= 200.0;
    }
    field converted_amount: Number {
        value == this.source_amount * this.exchange_rate;
    }
    field fee_pct: Number {
        value >= 0.1;
        value <= 5.0;
    }
    field fee_amount: Number {
        value == this.converted_amount * (this.fee_pct / 100.0);
    }
    field net_amount: Number {
        value == this.converted_amount - this.fee_amount;
    }
    field currency_pair: String {
        value IN ["USD/EUR", "USD/GBP", "USD/JPY", "EUR/GBP", "USD/CAD"];
    }
}

OFF_utility_bill_calculation.invariants_dsl:
spec UtilityBill {
    field kwh_used: Number {
        value >= 0.0;
        value <= 20000.0;
    }
    field rate_per_kwh: Number {
        value >= 0.05;
        value <= 0.50;
    }
    field energy_cost: Number {
        value == this.kwh_used * this.rate_per_kwh;
    }
    field fixed_service_charge: Number {
        value >= 5.0;
        value <= 50.0;
    }
    field total_bill: Number {
        value == this.energy_cost + this.fixed_service_charge;
    }
    field billing_tier: String {
        value IN ["residential", "commercial", "industrial"];
    }
}
